      write: prepared.write,
      payload: prepared.payload,
      metadata: prepared.metadata,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];

const httpOutput = $input.first().json || {};
const prepared = $("Prepare HubSpot Contact Create Request").first().json;
const context = prepared.context;

const recordId = httpOutput.id || null;

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      destination: {
        ...context.destination,
        record_id: recordId
      },
      write: {
        status: "created",
        fields_written: context.write.fields_written
      },
      payload: context.payload,
      metadata: context.metadata,
      error: null,
      next_action: context.next_action
    }
  }
];

const input = $input.first().json || {};

function fail({ code, message, details = [], inputSnapshot = {} }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C2-A3",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        destination: {
          type: "hubspot",
          object_type: input.config?.object_type || "contacts",
          record_id: null
        },
        write: {
          status: "failed",
          fields_written: []
        },
        payload: input.input?.payload || {},
        metadata: input.input?.metadata || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log",
        input_snapshot: inputSnapshot
      }
    }
  ];
}

function getByPath(obj, path) {
  return path.split(".").reduce((acc, key) => {
    if (acc && Object.prototype.hasOwnProperty.call(acc, key)) {
      return acc[key];
    }
    return undefined;
  }, obj);
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty.",
    inputSnapshot: input
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object.",
    inputSnapshot: input
  });
}

const validatedInput = input.input;
const config = input.config || {};

if (validatedInput.success !== true) {
  return fail({
    code: "UPSTREAM_VALIDATION_FAILED",
    message: "C2-A3 will not write records when upstream validation failed.",
    details: [
      {
        upstream_component: validatedInput.component_id || null,
        upstream_error: validatedInput.error || null
      }
    ],
    inputSnapshot: input
  });
}

if (!config.object_type) {
  return fail({
    code: "MISSING_OBJECT_TYPE",
    message: "config.object_type is required.",
    inputSnapshot: input
  });
}

if (config.object_type !== "contacts") {
  return fail({
    code: "UNSUPPORTED_OBJECT_TYPE",
    message: "C2-A3 v1 only supports HubSpot contacts.",
    details: [{ object_type: config.object_type }],
    inputSnapshot: input
  });
}

if (!config.field_map || typeof config.field_map !== "object") {
  return fail({
    code: "MISSING_FIELD_MAP",
    message: "config.field_map is required.",
    inputSnapshot: input
  });
}

const properties = {};
const fieldsWritten = [];

for (const [sourcePath, hubspotProperty] of Object.entries(config.field_map)) {
  const value = getByPath(validatedInput, sourcePath);
  if (value !== undefined && value !== null && value !== "") {
    properties[hubspotProperty] = String(value);
    fieldsWritten.push(hubspotProperty);
  }
}

// Add extra tracking fields only if mapped/custom properties exist later.
// For v1, do not send unknown HubSpot properties unless explicitly mapped.

if (!properties.email) {
  return fail({
    code: "MISSING_EMAIL_PROPERTY",
    message: "HubSpot contact creation requires an email property in the mapped properties.",
    details: [{ field: "email", issue: "email property missing after field mapping." }],
    inputSnapshot: input
  });
}

return [
  {
    json: {
      stop_before_http: false,
      request: {
        object_type: config.object_type,
        url: "https://api.hubapi.com/crm/v3/objects/contacts",
        body: {
          properties
        }
      },
      context: {
        component_id: "C2-A3",
        component_version: "v1",
        event_id: validatedInput.event_id || null,
        event_type: validatedInput.event_type || null,
        destination: {
          type: "hubspot",
          object_type: config.object_type,
          record_id: null
        },
        write: {
          status: "prepared",
          fields_written: fieldsWritten
        },
        payload: validatedInput.payload || {},
        metadata: validatedInput.metadata || {},
        next_action: config.default_next_action || "notify_team"
      }
    }
  }
];
